def format_rate(rate):
    val=rate*100000.0
    if val < 4294967296 and abs(val-round(val))<0.001 and int(round(val))%100000==0:
        s=str(int(round(rate)))
        if len(s)<10: s=s+" "*(10-len(s))
        return s
    return f"{rate:.6f}"

