PROTO_OFFSETS = {'T':0,'U':65536,'S':131072,'I':196608,'O':196608+256}
PROTO_MAX = {'T':65535,'U':65535,'S':65535,'I':65535,'O':255}

def parse_ports_into(state, spec, is_exclude):
    # returns None, may raise FatalParse after printing messages
    i=0; n=len(spec)
    proto='T'
    proto_offset=0
    # state proto persists across elements in this spec only; each spec reset to TCP? Observed -pU:53 multiple calls: second call -p80 gave TCP 80 not UDP, so reset per spec.
    while i<n:
        # skip spaces and? Leading spaces before element
        # Original skips whitespace at start of element
        while i<n and spec[i] in ' \t\r\n':
            i+=1
        if i>=n: break
        c=spec[i]
        # protocol prefix?
        if c.isalpha():
            # if next is colon
            if i+1<n and spec[i+1]==':':
                pc=c.upper()
                if pc not in PROTO_OFFSETS:
                    eprint(f"bad port character = {c}\n")
                    eprint(f"[-] FAIL: bad target port: {spec}\n    Hint: a port is a number [0..65535]\n")
                    raise FatalParse(1)
                proto=pc; proto_offset=PROTO_OFFSETS[pc]
                i+=2
                # after proto, proceed to number parsing in same iteration; need maybe skip? no spaces observed fail if space after colon? Let's test later: "U: 53" ?
                # continue to parse number below (no loop)
            else:
                break
        elif c==',':
            # At start of an element, comma stops? Original ,80 -> empty, 80,,443 stops.
            break
        elif not (c.isdigit() or c=='-'):
            break
        # parse low
        low=None; high=None
        if i<n and spec[i]=='-':
            low=1; i+=1
            # parse high next
            start=i
            while i<n and spec[i].isdigit(): i+=1
            if i>start:
                high=int(spec[start:i])
            else:
                high=PROTO_MAX[proto] if proto=='O' else 65535
                # For O low default? above high determined
                # if proto O, max displayed range internal high is 511 -> high value 255
            # validate below
        else:
            # digits
            start=i
            while i<n and spec[i].isdigit(): i+=1
            if i==start:
                break
            low=int(spec[start:i])
            if i<n and spec[i]=='-':
                i+=1
                start2=i
                while i<n and spec[i].isdigit(): i+=1
                if i>start2:
                    high=int(spec[start2:i])
                else:
                    high=PROTO_MAX[proto] if proto=='O' else 65535
            else:
                high=low
        # validation
        maxv=PROTO_MAX[proto]
        # For proto I/T/U/S max 65535; O max 255. Also low/high check
        if low is None or high is None or low>maxv or high>maxv or low>high or low<0 or high<0:
            eprint(f"[-] FAIL: bad target port: {spec}\n    Hint: a port is a number [0..65535]\n")
            raise FatalParse(1)
        begin=proto_offset+low; end=proto_offset+high
        if is_exclude:
            state.exclude_ports_list.add(begin,end)
            state.ports.remove(begin,end)
        else:
            state.ports.add(begin,end)
            for eb,ee in state.exclude_ports_list.ranges:
                state.ports.remove(eb,ee)
        # after element, if next char is comma, consume and continue; else break
        if i<n and spec[i]==',':
            i+=1
            # If following char is ',' or end? Original stops after empty element: loop top will handle: if next is ',' break; if next is alpha without colon etc break; if digits continue; if spaces skip then digits continue.
