def port_list_to_string(ports):
    parts=[]
    for b,e in ports.ranges:
        block=b//65536
        if block==0:
            prefix=""
            bb=b; ee=e
        elif block==1:
            prefix="U:"; bb=b-65536; ee=e-65536
        elif block==2:
            prefix="S:"; bb=b-131072; ee=e-131072
        else:
            prefix="I:"; bb=b-196608; ee=e-196608
        if bb==ee:
            parts.append(f"{prefix}{bb}")
        else:
            parts.append(f"{prefix}{bb}-{ee}")
    return ",".join(parts)

