                elif ch=='F':
                    eprint("nmap(-F): unsupported, no slow/fast mode\n"); sys.exit(1)
                elif ch=='O':
                    eprint("nmap(-O): unsupported, OS detection is too complex\n"); sys.exit(1)
                elif ch=='R':
                    eprint("nmap(-R): unsupported. This code will never do DNS lookups.\n"); sys.exit(1)
                elif ch=='T':
