                self.write_bytes(f"{proto.upper()} banner\t            {svc}[{rec.port:5d}]\t\tfrom {ip}  ttl {rec.ttl} \n")
            else:
                svc=service_by_port(rec.port)
                # Format observed: 'TCP open\t            http[   80]\t\tfrom 10.0.0.5  ttl 64 \n'
                # upper proto, kind, tab, padding to ??? svc right? Let's replicate approximate pattern: proto upper + space + kind + \t + svc with width ??
                # In observed: "TCP open\t            http[   80]\t\tfrom 10.0.0.5  ttl 64 \n"
