hdr=b"masscan/1.1\n"+b"\x00"*87
def v6status(ts,ip,port,proto=6,kind=10):
    ipv6=ipaddress.IPv6Address(ip).packed
    pl=struct.pack(">I",ts)+bytes([proto])+struct.pack(">H",port)+bytes([0x12,64,6])+ipv6
    return rec(kind,pl)
def v6banner(ts,ip,port,data=b"HelloV6"):
    ipv6=ipaddress.IPv6Address(ip).packed
    pl=struct.pack(">I",ts)+bytes([6])+struct.pack(">H",port)+struct.pack(">H",5)+bytes([0,6])+ipv6+data
    return rec(13,pl)
