import subprocess, re, os
ORIG="/tmp/orig_executable"; NEW="./executable"
def norm(b):
    s=b.decode('latin-1')
    s=re.sub(r'^seed = \d+','seed = X',s,flags=re.M)
    s=re.sub(r'start="\d+"','start="T"',s); s=re.sub(r'<finished time="\d+" timestr="[^"]+"','<finished time="T" timestr="D"',s); s=re.sub(r'# Masscan done at .*','# Masscan done at D',s)
    return s.encode('latin-1')
def run(exe,args):
    ro=[]
    for a in args:
        if a=="{OUT}":
            out=f"/tmp/rs/out_{'o' if exe==ORIG else 'n'}"
            try: os.remove(out)
            except: pass
            ro.append(out)
        else: ro.append(a)
    p=subprocess.run([exe]+ro,capture_output=True,timeout=5)
    fc=b""
    if "{OUT}" in args:
        out=ro[args.index("{OUT}")] if False else f"/tmp/rs/out_{'o' if exe==ORIG else 'n'}"
        if os.path.exists(out): fc=open(out,"rb").read()
    return p.returncode, norm(p.stdout), norm(p.stderr), norm(fc)
